"use client";

import * as React from "react";
import { cn } from "../../lib/utils";

// Radio: generated by UIX from the design system. Same variants and sizes as the Figma component.

const radioClasses = "peer size-5 shrink-0 cursor-pointer appearance-none rounded-full transition-colors border border-line-strong bg-surface hover:border-line-brand checked:border-transparent checked:hover:border-transparent checked:bg-brand checked:hover:bg-brand-hover focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:cursor-not-allowed disabled:border-line-default disabled:bg-disabled checked:disabled:bg-disabled";

export interface RadioProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size"> {
  label?: React.ReactNode;
}

const Radio = React.forwardRef<HTMLInputElement, RadioProps>(
  ({ className, label, ...props }, ref) => {
    const box = (
      <span className="relative inline-flex size-5 shrink-0">
        <input ref={ref} type="radio" data-slot="radio" data-kind="toggle" className={cn(radioClasses, className)} {...props} />
        <span aria-hidden className="pointer-events-none absolute inset-0 m-auto opacity-0 rounded-full peer-checked:opacity-100 size-2 bg-fg-on-brand peer-disabled:bg-fg-disabled" />
      </span>
    );
    return (
      label ? (
        <label className="inline-flex cursor-pointer items-center gap-2 text-body-medium text-fg-primary has-[:disabled]:cursor-not-allowed has-[:disabled]:text-fg-disabled">
          {box}
          <span>{label}</span>
        </label>
      ) : (
        box
      )
    );
  },
);
Radio.displayName = "Radio";

export { Radio };
